package homereset

import (
	"context"
	"crypto/rand"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"math/big"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"golang.org/x/sys/unix"
)

const snapshotRoot = "/var/lib/home-snapshots"
const resetState = snapshotRoot + "/.workspace-reset"
const publishedSnapshots = snapshotRoot + "/workspace"

// Config is generated by the system configuration, not supplied by a student
// or a reset CLI. Runtime integration must keep the login barrier held until
// Reset returns successfully and must never retry within the same boot.
type Config struct {
	User           string   `json:"user"`
	Seed           string   `json:"seed"`
	EphemeralPaths []string `json:"ephemeralPaths"`
	Wallpapers     []string `json:"wallpapers"`
	Btrfs          string   `json:"btrfs"`
	Dconf          string   `json:"dconf"`
	Systemctl      string   `json:"systemctl"`
}

type resetAccount struct {
	uid, gid, snapshotGID int
	home                  string
}

// Reset implements a boot-only reset. A durable pending record with a phase
// survives process failure and reboot. The next boot recovers only states that
// prove the original home is untouched or safely retained in a read-only
// snapshot, at most once after the home may have changed, and fails closed for
// every other state until an administrator inspects it (ADR 0029).
func Reset(config Config) error { return runReset(config, copyTree) }

// ResetConfigured is the fixed systemd entry point. The configuration must
// resolve to an immutable store file below the root-controlled /etc tree.
func ResetConfigured() error {
	if os.Geteuid() != 0 {
		return errors.New("reset requires root")
	}
	if err := trustedDirectory("/etc"); err != nil {
		return err
	}
	const configPath = "/etc/nixorium-workspace-reset.json"
	info, err := os.Lstat(configPath)
	if err != nil {
		return err
	}
	if info.Sys().(*syscall.Stat_t).Uid != 0 {
		return errors.New("reset configuration is not root-owned")
	}
	resolved, err := filepath.EvalSymlinks(configPath)
	if err != nil {
		return err
	}
	if err := immutableStoreFile(resolved); err != nil {
		return err
	}
	data, err := readBounded(resolved, 128*1024)
	if err != nil {
		return err
	}
	var config Config
	if err := decodeStrict(data, &config); err != nil {
		return err
	}
	return Reset(config)
}

type restoreFunc func(string, string, int, int) error

// Phases of the durable pending record. The original home is untouched until
// the restore phase is durable, which is written only after the sanitized
// read-only snapshot is durable. The published phase follows the durable
// publication of that snapshot.
const (
	phasePrepare   = "prepare"
	phaseRestore   = "restore"
	phasePublished = "published"
)

type pendingRecord struct {
	SchemaVersion int    `json:"schemaVersion"`
	Seed          string `json:"seed"`
	User          string `json:"user"`
	Phase         string `json:"phase,omitempty"`
}

// resetEvidence is the validated content of the private state directory.
type resetEvidence struct {
	pending                          *pendingRecord
	prepared, keyfiles, previous     bool
	recovery, pendingNew, successNew bool
}

func runReset(config Config, restore restoreFunc) error {
	account, err := preflight(config)
	if err != nil {
		return fmt.Errorf("reset preflight: %w", err)
	}
	if err := privateDirectory(resetState, 0700, 0); err != nil {
		return err
	}
	lock, err := os.OpenFile(resetState+"/lock", os.O_CREATE|os.O_RDWR|syscall.O_NOFOLLOW, 0600)
	if err != nil {
		return err
	}
	defer lock.Close()
	if err := unix.Flock(int(lock.Fd()), unix.LOCK_EX|unix.LOCK_NB); err != nil {
		return errors.New("another reset owns the lock")
	}
	evidence, err := inspectState()
	if err != nil {
		return err
	}
	if err := privateDirectory(publishedSnapshots, 0750, account.snapshotGID); err != nil {
		return err
	}
	if err := inspectSnapshots(config); err != nil {
		return err
	}
	// Repeat the session guard after acquiring the lock and inspecting storage.
	if err := loginBarrier(config, account.uid); err != nil {
		return err
	}
	if evidence.pending != nil {
		return recoverReset(config, account, evidence, restore)
	}
	return freshReset(config, account, restore)
}

func freshReset(config Config, account resetAccount, restore restoreFunc) error {
	record, err := pendingJSON(config, phasePrepare)
	if err != nil {
		return err
	}
	if err := writeExclusive(resetState+"/pending.json", record); err != nil {
		return err
	}
	// Until the restore phase is durable the original home is untouched. A
	// failure removes this attempt's own work, so a transient refusal does not
	// block later boots; an interruption leaves the prepare phase to recovery.
	if err := prepareSnapshot(config, account); err != nil {
		if discardErr := discardPreparation(config); discardErr != nil {
			return errors.Join(err, fmt.Errorf("discard incomplete preparation: %w", discardErr))
		}
		return err
	}
	if err := setPhase(config, phaseRestore); err != nil {
		return err
	}
	return finishRestore(config, account, restore)
}

// recoverReset runs at most one automatic attempt for an interrupted reset
// that may have changed the home. Every unproven state fails closed.
func recoverReset(config Config, account resetAccount, evidence resetEvidence, restore restoreFunc) error {
	record := evidence.pending
	if record.User != config.User {
		return errors.New("incomplete reset evidence names another account; administrator recovery is required")
	}
	if evidence.recovery {
		return errors.New("automatic recovery of an interrupted reset already failed; administrator recovery is required")
	}
	phase := record.Phase
	if phase == "" {
		// Schema 1 records have no phase. Only a read-only snapshot shows that
		// the original home may have been removed after it was retained.
		phase = phasePrepare
		if evidence.previous {
			readOnly, err := readOnlySubvolume(config, resetState+"/previous")
			if err != nil {
				return err
			}
			if readOnly {
				phase = phaseRestore
			}
		}
	}
	switch phase {
	case phasePrepare:
		fmt.Fprintln(os.Stderr, "Discarding an interrupted student workspace reset that had not changed the home.")
		if err := discardPreparation(config); err != nil {
			return fmt.Errorf("discard interrupted preparation; administrator recovery is required: %w", err)
		}
		return freshReset(config, account, restore)
	case phaseRestore:
		if !evidence.previous {
			return errors.New("interrupted restore has no retained snapshot; administrator recovery is required")
		}
		readOnly, err := readOnlySubvolume(config, resetState+"/previous")
		if err != nil {
			return err
		}
		if !readOnly {
			return errors.New("interrupted restore has a writable snapshot; administrator recovery is required")
		}
		fmt.Fprintln(os.Stderr, "Completing an interrupted student workspace reset from its retained snapshot.")
		for _, name := range []string{"prepared", "keyfiles"} {
			if err := removePrivateTree(resetState + "/" + name); err != nil {
				return err
			}
		}
		for _, name := range []string{"pending.new", "success.new"} {
			if err := removeIfPresent(resetState + "/" + name); err != nil {
				return err
			}
		}
		if err := prepareHome(config); err != nil {
			return err
		}
		if err := loginBarrier(config, account.uid); err != nil {
			return err
		}
		// Preparation never touches the home, so a failure above may repeat.
		// The single automatic attempt starts with the first home change.
		if err := writeRecoveryMarker(phase); err != nil {
			return err
		}
		return finishRestore(config, account, restore)
	case phasePublished:
		fmt.Fprintln(os.Stderr, "Finishing an interrupted student workspace reset after publication.")
		if err := writeRecoveryMarker(phase); err != nil {
			return err
		}
		return finishPublished(config)
	}
	return errors.New("unknown reset phase; administrator recovery is required")
}

func prepareHome(config Config) error {
	if err := os.Mkdir(resetState+"/prepared", 0700); err != nil {
		return err
	}
	if err := copyTree(config.Seed+"/home", resetState+"/prepared", 0, 0); err != nil {
		return err
	}
	return prepareWallpaper(config)
}

func prepareSnapshot(config Config, account resetAccount) error {
	if err := prepareHome(config); err != nil {
		return err
	}
	if err := loginBarrier(config, account.uid); err != nil {
		return err
	}
	if err := command(config.Btrfs, "subvolume", "snapshot", account.home, resetState+"/previous"); err != nil {
		return err
	}
	// The snapshot is initially reachable only by root. Sanitize it before
	// publication, leaving the original home untouched if exclusions fail.
	if err := RemoveEphemeral(resetState+"/previous", config.EphemeralPaths); err != nil {
		return err
	}
	if err := snapshotPermissions(resetState+"/previous", account.snapshotGID); err != nil {
		return err
	}
	if err := command(config.Btrfs, "property", "set", "-ts", resetState+"/previous", "ro", "true"); err != nil {
		return err
	}
	if err := syncFilesystem(resetState); err != nil {
		return err
	}
	return loginBarrier(config, account.uid)
}

// finishRestore replaces the home from the prepared seed. It requires a
// durable restore phase and a read-only retained snapshot.
func finishRestore(config Config, account resetAccount, restore restoreFunc) error {
	if err := cleanHome(account.home, true); err != nil {
		return err
	}
	if err := restore(resetState+"/prepared", account.home, account.uid, account.gid); err != nil {
		return fmt.Errorf("home restore incomplete; login must remain blocked: %w", err)
	}
	if err := applyHomeFilesModes(config.Seed, account.home); err != nil {
		return fmt.Errorf("home file permissions incomplete; login must remain blocked: %w", err)
	}
	if err := os.Chmod(account.home, 0700); err != nil {
		return err
	}
	if err := syncFilesystem(account.home); err != nil {
		return err
	}
	if err := publishSnapshot(config, account.snapshotGID); err != nil {
		return err
	}
	if err := setPhase(config, phasePublished); err != nil {
		return err
	}
	return finishPublished(config)
}

// finishPublished removes the retained snapshot only once its published copy
// is verified, then records success.
func finishPublished(config Config) error {
	if _, err := os.Lstat(resetState + "/previous"); err == nil {
		published, err := snapshotPublished(config)
		if err != nil {
			return err
		}
		if !published {
			return errors.New("published snapshot does not match the retained snapshot; administrator recovery is required")
		}
		if err := command(config.Btrfs, "subvolume", "delete", resetState+"/previous"); err != nil {
			return err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	for _, name := range []string{"prepared", "keyfiles"} {
		if err := removePrivateTree(resetState + "/" + name); err != nil {
			return err
		}
	}
	for _, name := range []string{"pending.new", "success.new"} {
		if err := removeIfPresent(resetState + "/" + name); err != nil {
			return err
		}
	}
	boot, err := readBounded("/proc/sys/kernel/random/boot_id", 128)
	if err != nil {
		return err
	}
	receipt, err := json.Marshal(struct {
		SchemaVersion int    `json:"schemaVersion"`
		Seed          string `json:"seed"`
		User          string `json:"user"`
		BootID        string `json:"bootID"`
	}{1, config.Seed, config.User, strings.TrimSpace(string(boot))})
	if err != nil {
		return err
	}
	if err := writeExclusive(resetState+"/success.new", receipt); err != nil {
		return err
	}
	if err := os.Rename(resetState+"/success.new", resetState+"/success.json"); err != nil {
		return err
	}
	if err := syncFilesystem(resetState); err != nil {
		return err
	}
	if err := removeIfPresent(resetState + "/recovery.json"); err != nil {
		return err
	}
	if err := os.Remove(resetState + "/pending.json"); err != nil {
		return err
	}
	return syncFilesystem(resetState)
}

// discardPreparation removes the work of a reset that has not changed the
// home. The pending record goes last, so an interruption stays recoverable.
func discardPreparation(config Config) error {
	if _, err := os.Lstat(resetState + "/previous"); err == nil {
		if err := command(config.Btrfs, "subvolume", "delete", resetState+"/previous"); err != nil {
			return err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	for _, name := range []string{"prepared", "keyfiles"} {
		if err := removePrivateTree(resetState + "/" + name); err != nil {
			return err
		}
	}
	for _, name := range []string{"pending.new", "success.new", "recovery.json"} {
		if err := removeIfPresent(resetState + "/" + name); err != nil {
			return err
		}
	}
	if err := syncFilesystem(resetState); err != nil {
		return err
	}
	if err := os.Remove(resetState + "/pending.json"); err != nil {
		return err
	}
	return syncFilesystem(resetState)
}

func pendingJSON(config Config, phase string) ([]byte, error) {
	data, err := json.Marshal(pendingRecord{SchemaVersion: 2, Seed: config.Seed, User: config.User, Phase: phase})
	if err != nil {
		return nil, err
	}
	return append(data, '\n'), nil
}

// setPhase replaces the pending record atomically. An interruption leaves the
// previous phase, which describes a state that is still true.
func setPhase(config Config, phase string) error {
	record, err := pendingJSON(config, phase)
	if err != nil {
		return err
	}
	if err := writeExclusive(resetState+"/pending.new", record); err != nil {
		return err
	}
	if err := os.Rename(resetState+"/pending.new", resetState+"/pending.json"); err != nil {
		return err
	}
	return syncFilesystem(resetState)
}

func writeRecoveryMarker(phase string) error {
	boot, err := readBounded("/proc/sys/kernel/random/boot_id", 128)
	if err != nil {
		return err
	}
	marker, err := json.Marshal(struct {
		SchemaVersion int    `json:"schemaVersion"`
		Phase         string `json:"phase"`
		BootID        string `json:"bootID"`
	}{1, phase, strings.TrimSpace(string(boot))})
	if err != nil {
		return err
	}
	return writeExclusive(resetState+"/recovery.json", marker)
}

func removePrivateTree(name string) error {
	if _, err := os.Lstat(name); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	if err := cleanHome(name, true); err != nil {
		return err
	}
	return os.Remove(name)
}

func removeIfPresent(name string) error {
	if err := os.Remove(name); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func readOnlySubvolume(config Config, name string) (bool, error) {
	output, err := commandOutput(config.Btrfs, "property", "get", "-ts", name, "ro")
	if err != nil {
		return false, fmt.Errorf("cannot read snapshot state; administrator recovery is required: %w", err)
	}
	switch strings.TrimSpace(string(output)) {
	case "ro=true":
		return true, nil
	case "ro=false":
		return false, nil
	}
	return false, errors.New("unexpected snapshot state; administrator recovery is required")
}

func preflight(config Config) (resetAccount, error) {
	var account resetAccount
	if os.Geteuid() != 0 {
		return account, errors.New("reset requires root")
	}
	if config.User == "" || config.User == "admin" || strings.ContainsAny(config.User, "/\\\x00\n\r ") {
		return account, errors.New("invalid managed account")
	}
	identity, err := user.Lookup(config.User)
	if err != nil {
		return account, err
	}
	account.uid, err = strconv.Atoi(identity.Uid)
	if err != nil || account.uid < 1000 || account.uid == 65534 {
		return account, errors.New("managed account must be a normal user")
	}
	account.gid, err = strconv.Atoi(identity.Gid)
	if err != nil {
		return account, err
	}
	group, err := user.LookupGroup("nixorium-staff")
	if err != nil {
		return account, err
	}
	account.snapshotGID, err = strconv.Atoi(group.Gid)
	if err != nil {
		return account, err
	}
	account.home = "/home/" + config.User
	if identity.HomeDir != account.home {
		return account, errors.New("managed account home differs from the configured path")
	}
	if err := validatePaths(config.EphemeralPaths); err != nil {
		return account, err
	}
	if err := validateSeed(config.Seed); err != nil {
		return account, err
	}
	for _, tool := range []struct{ path, base string }{{config.Btrfs, "btrfs"}, {config.Dconf, "dconf"}, {config.Systemctl, "systemctl"}} {
		if filepath.Base(tool.path) != tool.base {
			return account, errors.New("unexpected reset tool")
		}
		if err := immutableStoreFile(tool.path); err != nil {
			return account, err
		}
	}
	if len(config.Wallpapers) > 128 {
		return account, errors.New("too many wallpapers")
	}
	for _, wallpaper := range config.Wallpapers {
		if err := immutableStoreFile(wallpaper); err != nil {
			return account, err
		}
	}
	if err := trustedDirectory("/home"); err != nil {
		return account, err
	}
	if err := trustedDirectory(snapshotRoot); err != nil {
		return account, err
	}
	home, err := mountedSubvolume(account.home, "/@home-"+config.User)
	if err != nil {
		return account, err
	}
	snapshots, err := mountedSubvolume(snapshotRoot, "/@snapshots")
	if err != nil {
		return account, err
	}
	// Btrfs reports a different st_dev for each subvolume. Do not compare it
	// across these roots. The snapshot ioctl additionally requires the same
	// filesystem and must succeed before any original home data is removed.
	if home.Mnt_id == snapshots.Mnt_id {
		return account, errors.New("home and snapshots must have distinct mounts")
	}
	if home.Uid != uint32(account.uid) || home.Gid != uint32(account.gid) || home.Mode&0777 != 0700 {
		return account, errors.New("unexpected home ownership or permissions")
	}
	if err := loginBarrier(config, account.uid); err != nil {
		return account, err
	}
	if err := cleanSelected(account.home, config.EphemeralPaths, false); err != nil {
		return account, err
	}
	if err := cleanHome(account.home, false); err != nil {
		return account, err
	}
	return account, nil
}

func trustedDirectory(name string) error {
	if !filepath.IsAbs(name) || filepath.Clean(name) != name {
		return errors.New("noncanonical trusted directory")
	}
	for current := name; ; current = filepath.Dir(current) {
		info, err := os.Lstat(current)
		if err != nil {
			return err
		}
		if !info.IsDir() || info.Sys().(*syscall.Stat_t).Uid != 0 || info.Mode().Perm()&0022 != 0 {
			return fmt.Errorf("untrusted reset directory: %s", current)
		}
		if current == "/" {
			return nil
		}
	}
}

func privateDirectory(name string, mode os.FileMode, gid int) error {
	if err := trustedDirectory(filepath.Dir(name)); err != nil {
		return err
	}
	err := os.Mkdir(name, mode)
	if err == nil {
		if err := os.Chown(name, 0, gid); err != nil {
			return err
		}
		if err := os.Chmod(name, mode); err != nil {
			return err
		}
	} else if !errors.Is(err, os.ErrExist) {
		return err
	}
	if err := trustedDirectory(name); err != nil {
		return err
	}
	info, err := os.Lstat(name)
	if err != nil {
		return err
	}
	if info.Mode().Perm() != mode || info.Sys().(*syscall.Stat_t).Gid != uint32(gid) {
		return errors.New("unexpected reset directory permissions")
	}
	return nil
}

func mountedSubvolume(name, subvolume string) (unix.Statx_t, error) {
	var result unix.Statx_t
	err := withDirectory(name, func(fd int, stat unix.Statx_t) error {
		var filesystem unix.Statfs_t
		if err := unix.Fstatfs(fd, &filesystem); err != nil {
			return err
		}
		if filesystem.Type != unix.BTRFS_SUPER_MAGIC || stat.Ino != 256 || stat.Mask&unix.STATX_SUBVOL == 0 {
			return errors.New("expected a Btrfs subvolume root")
		}
		mounts, err := os.ReadFile("/proc/self/mountinfo")
		if err != nil {
			return err
		}
		for _, line := range strings.Split(string(mounts), "\n") {
			fields := strings.Fields(line)
			if len(fields) > 6 && fields[0] == strconv.FormatUint(stat.Mnt_id, 10) && fields[3] == subvolume && fields[4] == name {
				result = stat
				return nil
			}
		}
		return errors.New("home or snapshot mount does not match the declared layout")
	})
	return result, err
}

func loginBarrier(config Config, uid int) error {
	if _, err := os.Lstat("/var/lib/systemd/linger/" + config.User); !errors.Is(err, os.ErrNotExist) {
		return errors.New("managed account must not have lingering enabled")
	}
	info, err := os.Lstat("/run/nologin")
	if err != nil {
		return errors.New("login barrier is not held")
	}
	if !info.Mode().IsRegular() || info.Sys().(*syscall.Stat_t).Uid != 0 || info.Mode().Perm()&0022 != 0 {
		return errors.New("untrusted login barrier")
	}
	for _, unit := range []string{"systemd-user-sessions.service", "display-manager.service"} {
		output, err := commandOutput(config.Systemctl, "show", "--property=ActiveState", "--value", "--no-ask-password", unit)
		if err != nil {
			return errors.New("cannot establish login service state")
		}
		if state := strings.TrimSpace(string(output)); state != "inactive" && state != "failed" {
			return errors.New("login services must be stopped before reset")
		}
	}
	entries, err := os.ReadDir("/proc")
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if _, err := strconv.Atoi(entry.Name()); err != nil {
			continue
		}
		data, err := os.ReadFile("/proc/" + entry.Name() + "/status")
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return err
		}
		found := false
		name := ""
		for _, line := range strings.Split(string(data), "\n") {
			if value, ok := strings.CutPrefix(line, "Name:"); ok {
				name = strings.TrimSpace(value)
				continue
			}
			if !strings.HasPrefix(line, "Uid:") {
				continue
			}
			fields := strings.Fields(line)
			if len(fields) != 5 {
				return errors.New("cannot establish process ownership")
			}
			found = true
			for _, field := range fields[1:] {
				if field == strconv.Itoa(uid) {
					// Name the process so the journal identifies the conflicting service.
					return fmt.Errorf("managed account still has running processes (pid %s, %s)", entry.Name(), strconv.QuoteToASCII(name))
				}
			}
		}
		if !found {
			return errors.New("cannot establish process ownership")
		}
	}
	return nil
}

func inspectState() (resetEvidence, error) {
	var evidence resetEvidence
	entries, err := os.ReadDir(resetState)
	if err != nil {
		return evidence, err
	}
	for _, entry := range entries {
		name := entry.Name()
		info, err := entry.Info()
		if err != nil {
			return evidence, err
		}
		owner := info.Sys().(*syscall.Stat_t).Uid
		switch name {
		case "lock", "success.json", "pending.json", "pending.new", "success.new", "recovery.json":
			if !info.Mode().IsRegular() || info.Mode().Perm() != 0600 || owner != 0 {
				return evidence, errors.New("untrusted reset state")
			}
		case "prepared", "keyfiles":
			if !info.IsDir() || owner != 0 || info.Mode().Perm()&0077 != 0 {
				return evidence, errors.New("untrusted reset state")
			}
		case "previous":
			if !info.IsDir() {
				return evidence, errors.New("untrusted reset state")
			}
			if err := withDirectory(resetState+"/previous", func(fd int, stat unix.Statx_t) error {
				parent, err := statEntry(unix.AT_FDCWD, resetState, 0)
				if err != nil {
					return err
				}
				if stat.Ino != 256 || stat.Subvol == parent.Subvol || stat.Mnt_id != parent.Mnt_id {
					return errors.New("retained snapshot is not a subvolume; administrator recovery is required")
				}
				return nil
			}); err != nil {
				return evidence, err
			}
		default:
			return evidence, fmt.Errorf("unexpected reset evidence %q; administrator recovery is required", name)
		}
		switch name {
		case "prepared":
			evidence.prepared = true
		case "keyfiles":
			evidence.keyfiles = true
		case "previous":
			evidence.previous = true
		case "recovery.json":
			evidence.recovery = true
		case "pending.new":
			evidence.pendingNew = true
		case "success.new":
			evidence.successNew = true
		}
	}
	data, err := readBounded(resetState+"/pending.json", 64*1024)
	if errors.Is(err, os.ErrNotExist) {
		if evidence.prepared || evidence.keyfiles || evidence.previous || evidence.recovery || evidence.pendingNew || evidence.successNew {
			return evidence, errors.New("incomplete reset evidence exists; administrator recovery is required")
		}
		return evidence, nil
	}
	if err != nil {
		return evidence, err
	}
	var record pendingRecord
	if err := decodeStrict(data, &record); err != nil {
		return evidence, fmt.Errorf("unreadable reset evidence; administrator recovery is required: %w", err)
	}
	valid := record.Seed != "" && record.User != ""
	switch record.SchemaVersion {
	case 1:
		valid = valid && record.Phase == ""
	case 2:
		valid = valid && (record.Phase == phasePrepare || record.Phase == phaseRestore || record.Phase == phasePublished)
	default:
		valid = false
	}
	if !valid {
		return evidence, errors.New("unsupported reset evidence; administrator recovery is required")
	}
	evidence.pending = &record
	return evidence, nil
}

func inspectSnapshots(config Config) error {
	if _, err := os.Lstat(publishedSnapshots); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	if err := trustedDirectory(publishedSnapshots); err != nil {
		return err
	}
	entries, err := os.ReadDir(publishedSnapshots)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if len(entry.Name()) != len("snapshot-1") || entry.Name() < "snapshot-1" || entry.Name() > "snapshot-5" {
			return errors.New("unexpected managed snapshot entry")
		}
		name := publishedSnapshots + "/" + entry.Name()
		if err := trustedDirectory(name); err != nil {
			return err
		}
		if err := withDirectory(name, func(fd int, stat unix.Statx_t) error {
			parent, err := statEntry(unix.AT_FDCWD, publishedSnapshots, 0)
			if err != nil {
				return err
			}
			if stat.Ino != 256 || stat.Subvol == parent.Subvol || stat.Mnt_id != parent.Mnt_id {
				return errors.New("invalid managed snapshot subvolume")
			}
			return nil
		}); err != nil {
			return err
		}
		output, err := commandOutput(config.Btrfs, "property", "get", "-ts", name, "ro")
		if err != nil || strings.TrimSpace(string(output)) != "ro=true" {
			return errors.New("managed snapshot is not read-only")
		}
	}
	return nil
}

func snapshotPermissions(name string, gid int) error {
	// Only the new private snapshot is traversed. Never chmod/chown a symlink
	// target, and never let staff see the snapshot before exclusion is complete.
	return filepath.WalkDir(name, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return nil
		}
		if err := os.Lchown(path, 0, gid); err != nil {
			return err
		}
		mode := os.FileMode(0640)
		if entry.IsDir() {
			mode = 0750
		}
		return os.Chmod(path, mode)
	})
}

// publishSnapshot is idempotent: an interrupted rotation resumes at its first
// free slot, and an existing copy of the retained snapshot is not repeated.
func publishSnapshot(config Config, gid int) error {
	if err := privateDirectory(publishedSnapshots, 0750, gid); err != nil {
		return err
	}
	published, err := snapshotPublished(config)
	if err != nil {
		return err
	}
	if published {
		return syncFilesystem(publishedSnapshots)
	}
	slot := 0
	for i := 1; i <= 5; i++ {
		if _, err := os.Lstat(publishedSnapshots + "/snapshot-" + strconv.Itoa(i)); errors.Is(err, os.ErrNotExist) {
			slot = i
			break
		} else if err != nil {
			return err
		}
	}
	if slot == 0 {
		if err := command(config.Btrfs, "subvolume", "delete", publishedSnapshots+"/snapshot-5"); err != nil {
			return err
		}
		slot = 5
	}
	for i := slot - 1; i >= 1; i-- {
		if err := os.Rename(publishedSnapshots+"/snapshot-"+strconv.Itoa(i), publishedSnapshots+"/snapshot-"+strconv.Itoa(i+1)); err != nil {
			return err
		}
	}
	// A read-only subvolume cannot be moved between different parents. Keep
	// the recovery copy read-only and publish another cheap metadata snapshot.
	if err := command(config.Btrfs, "subvolume", "snapshot", "-r", resetState+"/previous", publishedSnapshots+"/snapshot-1"); err != nil {
		return err
	}
	return syncFilesystem(publishedSnapshots)
}

// snapshotPublished reports whether snapshot-1 was taken from the retained
// snapshot, using the Btrfs parent UUID.
func snapshotPublished(config Config) (bool, error) {
	if _, err := os.Lstat(publishedSnapshots + "/snapshot-1"); errors.Is(err, os.ErrNotExist) {
		return false, nil
	} else if err != nil {
		return false, err
	}
	retained, _, err := subvolumeUUIDs(config, resetState+"/previous")
	if err != nil {
		return false, err
	}
	_, parent, err := subvolumeUUIDs(config, publishedSnapshots+"/snapshot-1")
	if err != nil {
		return false, err
	}
	return parent == retained, nil
}

func subvolumeUUIDs(config Config, name string) (string, string, error) {
	output, err := commandOutput(config.Btrfs, "subvolume", "show", name)
	if err != nil {
		return "", "", fmt.Errorf("btrfs subvolume show failed: %w: %s", err, strings.TrimSpace(string(output)))
	}
	uuid, parent := "", ""
	for _, line := range strings.Split(string(output), "\n") {
		key, value, found := strings.Cut(strings.TrimSpace(line), ":")
		if !found {
			continue
		}
		switch key {
		case "UUID":
			uuid = strings.TrimSpace(value)
		case "Parent UUID":
			parent = strings.TrimSpace(value)
		}
	}
	if uuid == "" || uuid == "-" {
		return "", "", errors.New("cannot identify a snapshot; administrator recovery is required")
	}
	return uuid, parent, nil
}

func prepareWallpaper(config Config) error {
	if len(config.Wallpapers) == 0 {
		return nil
	}
	index, err := rand.Int(rand.Reader, big.NewInt(int64(len(config.Wallpapers))))
	if err != nil {
		return err
	}
	picture := "file://" + config.Wallpapers[index.Int64()]
	if err := os.Mkdir(resetState+"/keyfiles", 0700); err != nil {
		return err
	}
	if err := copyFile(config.Seed+"/dconf/00-workspace", resetState+"/keyfiles/00-workspace"); err != nil {
		return err
	}
	text := "[org/gnome/desktop/background]\npicture-uri='" + picture + "'\npicture-uri-dark='" + picture + "'\npicture-options='zoom'\n\n[org/gnome/desktop/screensaver]\npicture-uri='" + picture + "'\npicture-options='zoom'\n"
	if err := writeExclusive(resetState+"/keyfiles/90-wallpaper", []byte(text)); err != nil {
		return err
	}
	if err := os.MkdirAll(resetState+"/prepared/.config/dconf", 0700); err != nil {
		return err
	}
	return command(config.Dconf, "compile", resetState+"/prepared/.config/dconf/user", resetState+"/keyfiles")
}

func writeExclusive(name string, data []byte) error {
	file, err := os.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	_, writeErr := file.Write(data)
	syncErr := file.Sync()
	closeErr := file.Close()
	if err := errors.Join(writeErr, syncErr, closeErr); err != nil {
		return err
	}
	return syncFilesystem(filepath.Dir(name))
}

func syncFilesystem(name string) error {
	fd, err := unix.Open(name, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		return err
	}
	defer unix.Close(fd)
	return unix.Syncfs(fd)
}

func command(binary string, args ...string) error {
	output, err := commandOutput(binary, args...)
	if err != nil {
		return fmt.Errorf("%s failed: %w: %s", filepath.Base(binary), err, strings.TrimSpace(string(output)))
	}
	return nil
}

// commandTimeout ends a btrfs, dconf or systemctl run that has not finished.
// These take seconds; a command stuck for minutes would hold the boot-time
// reset forever; the reset fails instead, and its pending record decides the
// next boot's recovery.
var commandTimeout = 5 * time.Minute

func commandOutput(binary string, args ...string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), commandTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, binary, args...)
	cmd.Env = []string{"LANG=C", "LC_ALL=C"}
	// Do not wait for a pipe that a stuck child's own children keep open.
	cmd.WaitDelay = 10 * time.Second
	return cmd.CombinedOutput()
}
